struct RGB colorConverter(int hexValue) {
  struct RGB rgbColor;
  rgbColor.r = ((hexValue >> 16) & 0xFF);  // Extracts the RR hex
  rgbColor.g = ((hexValue >> 8) & 0xFF);   // Extracts the GG hex
  rgbColor.b = ((hexValue) & 0xFF);        // Extracts the BB hex
  return rgbColor;
}

