void drawShallowSea(){
  for (int xval = 0; xval < 64; xval++){
    for (int yval = 0; yval < 16; yval++){
      int idx = 64 * yval + xval;
      int hex = SHALLOW_SEA[idx];
      RGB color = colorConverter(hex);
      matrix.drawPixel(xval, yval, matrix.color565(color.r, color.g, color.b));
    }
  }
  matrix.show();
}

