//WARNING: attempting to animate the array in this manner signifigantly lags the drawing process. Find a better way to animate it, or animate it using the old way.
void drawFlyingBee(int x_off, int y_off){
  for (int xval = 0; xval < 32; xval++){
    for (int yval = 0; yval < 16; yval++){
      int idx = 32 * yval + xval;
      int hex = the_bee_[idx];
      RGB color = colorConverter(hex);
      matrix.drawPixel(xval + x_off, yval + y_off, matrix.color565(color.r, color.g, color.b));
    }
  }
  matrix.show();
}

